#include <windows.h>
#include <bcrypt.h>

#pragma comment(lib, "bcrypt.lib")

int main() {
    BCRYPT_ALG_HANDLE algorithm = nullptr;
    NTSTATUS status = BCryptOpenAlgorithmProvider(&algorithm, BCRYPT_RNG_ALGORITHM,
                                                  nullptr, 0);
    if (!BCRYPT_SUCCESS(status)) {
        return 1;
    }

    unsigned char bytes[32]{};
    status = BCryptGenRandom(algorithm, bytes, static_cast<ULONG>(sizeof(bytes)), 0);
    if (BCRYPT_SUCCESS(status)) {
        // Use the bytes as random data.
        SecureZeroMemory(bytes, sizeof(bytes));
    }

    BCryptCloseAlgorithmProvider(algorithm, 0);
    return BCRYPT_SUCCESS(status) ? 0 : 1;
}

