int main() {
    const BYTE data[] = { 'e', 'x', 'a', 'm', 'p', 'l', 'e' };
    DWORD length = 0;
    CryptBinaryToStringA(data, sizeof(data),
        CRYPT_STRING_BASE64 | CRYPT_STRING_NOCRLF, nullptr, &length);

    auto text = static_cast<LPSTR>(LocalAlloc(LPTR, length));
    if (text != nullptr &&
        CryptBinaryToStringA(data, sizeof(data),
