#include <stdio.h>

#pragma comment(lib, "advapi32.lib")

int main() {
    HCRYPTPROV provider = 0;
    HCRYPTHASH hash = 0;
    HCRYPTKEY key = 0;
    CryptAcquireContextA(&provider, nullptr, nullptr, PROV_RSA_AES,
        CRYPT_VERIFYCONTEXT);
    CryptCreateHash(provider, CALG_SHA_256, 0, 0, &hash);

    const char password[] = "example password";
    CryptHashData(hash, reinterpret_cast<const BYTE*>(password),
        sizeof(password) - 1, 0);
    CryptDeriveKey(provider, CALG_AES_128, hash, 0, &key);

    BYTE data[64] = "example";
    DWORD length = 7;
    if (CryptEncrypt(key, 0, TRUE, 0, data, &length, sizeof(data))) {
        if (CryptDecrypt(key, 0, TRUE, 0, data, &length)) {
            printf("Decrypted %lu bytes.\n", length);
        }
    }

    CryptDestroyKey(key);
    CryptDestroyHash(hash);
    CryptReleaseContext(provider, 0);
    return 0;
}

