int main() {
    const char text[] = "example";
    DATA_BLOB input = {};
    input.pbData = reinterpret_cast<BYTE*>(const_cast<char*>(text));
    input.cbData = sizeof(text) - 1;

    DATA_BLOB protected_data = {};
    DATA_BLOB output = {};
    if (CryptProtectData(&input, L"NtExplorer example", nullptr, nullptr,
            nullptr, CRYPTPROTECT_UI_FORBIDDEN, &protected_data)) {
        if (CryptUnprotectData(&protected_data, nullptr, nullptr, nullptr,
                nullptr, CRYPTPROTECT_UI_FORBIDDEN, &output)) {
            printf("Unprotected %lu bytes.\n", output.cbData);
            LocalFree(output.pbData);
        }
        LocalFree(protected_data.pbData);
    }
    return 0;
}

