int main() {
    char temp_path[MAX_PATH] = {};
    char file_path[MAX_PATH] = {};
    GetTempPathA(MAX_PATH, temp_path);
    GetTempFileNameA(temp_path, "nte", 0, file_path);

    HANDLE file = CreateFileA(file_path, GENERIC_WRITE, 0, nullptr,
        CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (file == INVALID_HANDLE_VALUE) {
        return 1;
    }
    CloseHandle(file);

    // EFS may be unavailable on some editions; failures are reported, not
    // escalated.
    if (EncryptFileA(file_path)) {
        printf("File encrypted.\n");
        if (DecryptFileA(file_path, 0)) {
            printf("File decrypted.\n");
        }
    } else {
        printf("EncryptFileA failed: %lu\n", GetLastError());
    }

    DeleteFileA(file_path);
    return 0;
}

